//! J2.3/J2.5: every hostile archive is refused **before any user data moves**
//! (spec 13.6, 13.8, 18.6A "Portable backup", 18.7(27)).
//!
//! The corpus lives in `tests/fixtures/archives/` and is regenerated by
//! `scripts/make-archive-fixtures.sh`. Each case is also rebuilt in a
//! temporary directory, so a stale committed fixture cannot quietly stop
//! testing anything.

use std::collections::BTreeMap;
use std::path::Path;

use plaudon_domain::time::Timestamp;
use plaudon_export::archive::restore::{ConflictPolicy, RestoreMode, RestoreOptions};
use plaudon_export::service::{ExportService, RestoreArchiveRequest};
use plaudon_integration_tests::fakes::hostile_archive::{self, CASES};
use plaudon_integration_tests::fakes::library;
use plaudon_persistence::archive::MediaArchive;
use plaudon_persistence::Database;

const NOW: Timestamp = Timestamp::from_millis(1_700_000_400_000);

fn committed_corpus() -> std::path::PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .ancestors()
        .nth(2)
        .expect("workspace root")
        .join("tests/fixtures/archives")
}

/// Everything observable about a library, so "unchanged" is checkable.
async fn snapshot(db: &Database, archive: &MediaArchive) -> BTreeMap<String, String> {
    let mut out = BTreeMap::new();
    for table in [
        "recordings",
        "media_assets",
        "recording_media",
        "transcript_revisions",
        "transcript_segments",
        "ai_outputs",
        "output_evidence",
        "sources",
        "source_items",
        "speakers",
        "recording_tags",
    ] {
        let count: i64 = sqlx::query_scalar(sqlx::AssertSqlSafe(format!(
            "SELECT COUNT(*) FROM {table}"
        )))
        .fetch_one(db.pool())
        .await
        .unwrap();
        out.insert(table.to_owned(), count.to_string());
    }
    let blobs = archive.list_blobs().unwrap();
    out.insert("blob_count".into(), blobs.len().to_string());
    for (relative, _) in &blobs {
        out.insert(
            format!("blob:{relative}"),
            library::digest_of(&archive.absolute(relative).unwrap()).to_hex(),
        );
    }
    out
}

async fn assert_rejected(case_file: &Path, attack: &str) {
    let dir = tempfile::tempdir().unwrap();
    let target = library::seed(&dir.path().join("library"), false).await;
    let service = ExportService::new(
        target.db.clone(),
        target.archive.clone(),
        target.root.clone(),
    );
    let before = snapshot(&target.db, &target.archive).await;

    // Inspection refuses it, writing nothing.
    let inspection = ExportService::inspect_archive_only(
        case_file,
        Some("correct horse battery staple"),
        &dir.path().join("probe"),
    );
    assert!(
        inspection.is_err(),
        "inspection accepted a hostile archive: {attack}"
    );

    // And so does a real restore attempt.
    let error = service
        .restore_portable_archive(
            &RestoreArchiveRequest {
                archive_path: case_file.to_path_buf(),
                password: Some("correct horse battery staple".into()),
                options: RestoreOptions {
                    mode: RestoreMode::Merge,
                    on_conflict: ConflictPolicy::Skip,
                    restore_tombstoned: false,
                },
            },
            NOW,
        )
        .await
        .err()
        .unwrap_or_else(|| panic!("restore accepted a hostile archive: {attack}"));
    let code = error.code().as_str();
    assert!(
        matches!(
            code,
            "ARCHIVE_REJECTED" | "ARCHIVE_DECRYPTION_FAILED" | "INTEGRITY_FAILED"
        ),
        "{attack} produced {code}: {error}"
    );

    let after = snapshot(&target.db, &target.archive).await;
    assert_eq!(before, after, "the library changed while refusing: {attack}");

    // Nothing is left in the private staging area either.
    let temp = target.root.join("temp");
    if temp.is_dir() {
        let leftovers: Vec<String> = std::fs::read_dir(&temp)
            .unwrap()
            .filter_map(Result::ok)
            .filter(|entry| {
                entry
                    .file_name()
                    .to_string_lossy()
                    .starts_with("plaudon-restore")
            })
            .map(|entry| entry.file_name().to_string_lossy().into_owned())
            .collect();
        assert!(leftovers.is_empty(), "staging left behind: {leftovers:?}");
    }
    target.db.close().await;
}

#[tokio::test]
async fn every_committed_hostile_archive_is_refused() {
    let corpus = committed_corpus();
    assert!(
        corpus.is_dir(),
        "the committed corpus is missing; run scripts/make-archive-fixtures.sh"
    );
    for case in CASES {
        let path = corpus.join(case.file_name);
        assert!(
            path.is_file(),
            "missing corpus file {}; run scripts/make-archive-fixtures.sh",
            case.file_name
        );
        assert_rejected(&path, case.attack).await;
    }
}

#[tokio::test]
async fn a_freshly_generated_corpus_is_refused_the_same_way() {
    let dir = tempfile::tempdir().unwrap();
    let corpus = dir.path().join("corpus");
    hostile_archive::write_corpus(&corpus);
    for case in CASES {
        assert_rejected(&corpus.join(case.file_name), case.attack).await;
    }
}

#[tokio::test]
async fn the_committed_corpus_matches_the_generator() {
    // A fixture that drifted from the generator is a fixture nobody updates.
    let dir = tempfile::tempdir().unwrap();
    let fresh = dir.path().join("corpus");
    hostile_archive::write_corpus(&fresh);
    let committed = committed_corpus();
    for case in CASES {
        let a = std::fs::read(fresh.join(case.file_name)).unwrap();
        let b = std::fs::read(committed.join(case.file_name)).unwrap();
        assert_eq!(
            a.len(),
            b.len(),
            "{} drifted; run scripts/make-archive-fixtures.sh",
            case.file_name
        );
        assert_eq!(
            a, b,
            "{} drifted; run scripts/make-archive-fixtures.sh",
            case.file_name
        );
    }
}

#[tokio::test]
async fn the_corpus_covers_every_documented_hostile_case() {
    // Spec 18.6A lists the cluster explicitly; keep the corpus aligned with it.
    let attacks: Vec<&str> = CASES.iter().map(|case| case.attack).collect();
    for required in [
        "escapes the destination",
        "absolute entry path",
        "symbolic link",
        "collide when case is folded",
        "deflate stream declaring gigabytes",
        "does not match its recorded digest",
        "format version this build does not read",
        "exhaust memory",
    ] {
        assert!(
            attacks.iter().any(|attack| attack.contains(required)),
            "the corpus has no case for {required}"
        );
    }
}
